from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def purge_expired(t):
        expired_keys = [k for k, (v, wt) in cache.items() if t >= wt + ttl]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == 'get':
            _, t, key = op
            if key in cache:
                value, wt = cache[key]
                if t >= wt + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)
        elif op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    # expired, treat as new
                    del cache[key]
                    purge_expired(t)
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
                    cache[key] = [value, t]
                    cache.move_to_end(key)
                else:
                    cache[key] = [value, t]
                    cache.move_to_end(key)
            else:
                purge_expired(t)
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        else:
            raise ValueError("Unknown op type")

    return results

